function sourceTags(source){return [...new Set((source.tags||[]).map(tag=>String(tag).trim().toUpperCase()).filter(Boolean))]}
function importSheetPosition(key=''){const match=String(key).match(/^(extended|multiversal)-vo-(\d+)$/);if(match)return{tag:match[1]==='extended'?'EMCU':'MVO',row:Number(match[2])};return /^mini-verse-vo-\d+$/.test(String(key))?{tag:'MVO',row:null}:null}
