function migrateMvoMiniVerseSources(){const migration='mvo-mini-verse-9-v2-order-repair',projects=state.projects.filter(project=>!(project.catalogMigrations||[]).includes(migration)&&(project.sources||[]).some(source=>sourceTags(source).includes('MVO')));if(!projects.length)return;for(const project of projects){project.worlds=project.worlds||[];project.sources=project.sources||[];let world=project.worlds.find(item=>universeMetadataKey(worldLabel(item))==='21642');if(!world){world={id:uid('world'),designation:'Earth-21642',name:'Earth-21642',description:'Multiversal VO · import'};project.worlds.push(world)}for(const [importKey,orderRow,title] of MVO_MINI_VERSE_ADDITIONS){const existing=project.sources.find(source=>source.importKey===importKey||(source.importKeys||[]).includes(importKey));if(existing){rememberSheetPosition(existing,'MVO',orderRow);continue}project.sources.push({id:uid('source'),importKey,importKeys:[importKey],importOrigin:'Mini-Verse VOs',title,type:'Serial',status:'Nierozpoczęte',date:'Jun, 2019',dateApprox:false,releaseDate:'2021-06-21',tags:['MVO'],sheetRows:{MVO:orderRow},worldIds:[world.id],createdAt:new Date().toISOString()})}project.catalogMigrations=[...(project.catalogMigrations||[]),migration]}save();render()}
