function ensureSourceRelationFields(){if($('#source-relation-fields'))return;const field=document.createElement('fieldset');field.id='source-relation-fields';field.className='event-picker source-relation-fields';field.innerHTML='<legend>Powiązanie z filmem lub serialem</legend><p>Używaj dla adaptacji, prequeli i komiksów bezpośrednio związanych z ekranowym źródłem.</p><div class="form-row"><label>Rodzaj powiązania<select id="source-relation-type"><option value="">Brak</option><option value="adaptation">Adaptacja</option><option value="prequel">Prequel</option><option value="tiein">Tie-in</option><option value="promotional">Materiał promocyjny</option><option value="associated">Nieoficjalnie łączony</option></select></label><label>Status kanoniczności<select id="source-canon-status"><option value="">Nieustalony</option><option value="kanoniczny">Kanoniczny</option><option value="oficjalny — kanon niejasny">Oficjalny — kanon niejasny</option><option value="niekanoniczny">Niekanoniczny</option><option value="nieoficjalny">Nieoficjalny</option></select></label></div><label>Znajdź film lub serial<input id="source-relation-search" type="search" autocomplete="off" placeholder="Zacznij wpisywać tytuł…"></label><div id="source-relation-selected" class="picker-selected"></div><div id="source-relation-results" class="picker-results"></div>';$('#source-worlds').after(field);$('#source-relation-search').addEventListener('input',populateSourceRelations)}
