function ensureQuickEventDialog(){if($('#quick-event-dialog'))return;const dialog=document.createElement('dialog');dialog.id='quick-event-dialog';dialog.className='dialog quick-event-dialog';dialog.innerHTML='<form id="quick-event-form"><button class="dialog-close" type="button" aria-label="Zamknij">×</button><p class="eyebrow">NOTATNIK OGLĄDANIA</p><h2>Szybkie wydarzenia</h2><p id="quick-source-name" class="quick-source-name"></p><label>Co się wydarzyło?<input id="quick-event-title" required autocomplete="off" placeholder="Krótka notatka"></label><div class="quick-event-grid"><label>Moment<input id="quick-event-moment" autocomplete="off" placeholder="00:42:15 / str. 18"></label><label>Data lub okres<input id="quick-event-date" autocomplete="off" placeholder="Opcjonalnie"></label><label>Świat<input id="quick-event-world" list="project-world-list" autocomplete="off" placeholder="Wpisz, aby wyszukać"></label><label>Bohaterowie<input id="quick-event-characters" list="quick-character-list" autocomplete="off" placeholder="Peter, May, Tony…"></label></div><label>Luźna notatka<input id="quick-event-note" autocomplete="off" placeholder="Opcjonalnie"></label><datalist id="quick-character-list"></datalist><p id="quick-event-feedback" class="quick-event-feedback">Enter zapisuje i przygotowuje następną pustą notatkę.</p><div class="quick-event-actions"><button id="quick-event-advanced" class="secondary-button" type="button">Pełny formularz</button><button class="primary-button" type="submit">Zapisz i następne ↵</button></div></form>';document.body.append(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();$('#quick-event-advanced').onclick=()=>{const sourceId=quickEventSourceId;dialog.close();openEventDialog(null,sourceId)};$('#quick-event-form').addEventListener('submit',saveQuickEvent)}
