function saveEvent(event){event.preventDefault();const project=activeProject(),title=$('#event-title').value.trim();if(!project||!title)return;const sourceId=selectedEventSourceIds[0]||null,sourceMoment=$('#event-source-moment').value.trim(),date=$('#event-date').value.trim(),relations=selectedEventRelations.map(relation=>({...relation})),legacyRelation=relations[0]||null,data={title,sourceId,sourceIds:[...selectedEventSourceIds],sourceMoment,sourceMoments:sourceId&&sourceMoment?{[sourceId]:sourceMoment}:{},characterIds:[...selectedEventCharacterIds],timeType:date?($('#event-date-approx').checked?'approx':'exact'):(legacyRelation?.type||'unknown'),date,dateApprox:$('#event-date-approx').checked,relations,relationEventId:legacyRelation?.eventId||null,world:selectedEventWorldLabels[0]||'',worldLinks:selectedEventWorldLabels.slice(1),place:$('#event-place').value.trim(),tags:$('#event-tags').value.split(',').map(tag=>tag.trim()).filter(Boolean),notes:$('#event-notes').value.trim(),inbox:$('#event-inbox').checked};if(editingEventId){const item=project.events.find(existing=>existing.id===editingEventId);if(item)Object.assign(item,data);editingEventId=null;save();$('#event-dialog').close();render();return}project.events.push({id:uid('event'),...data,createdAt:new Date().toISOString()});save();event.currentTarget.reset();selectedEventRelations=[];selectedEventCharacterIds=[];selectedEventWorldLabels=[];selectedEventSourceIds=sourceId?[sourceId]:[];$('#event-source-moment').value='';$('#event-inbox').checked=true;populateEventSources();populateEventCharacters();populateEventWorlds();renderRelationPicker();render();$('#event-title').focus()}

