$('.main').addEventListener('click',event=>{const button=event.target.closest('button[data-id]');if(!button)return;const project=activeProject(),id=button.dataset.id;if(button.classList.contains('add-event-from-source'))openQuickEventDialog(id);if(button.classList.contains('edit-source'))openSourceDialog(id);if(button.classList.contains('edit-event'))openEventDialog(id);if(button.classList.contains('edit-character'))openCharacterDialog(id);if(button.classList.contains('edit-world'))openWorldDialog(null,id);if(button.classList.contains('delete-source')&&confirm('Usunąć to źródło? Powiązane wydarzenia pozostaną w projekcie.')){project.sources=project.sources.filter(source=>source.id!==id);project.events.forEach(item=>{if(item.sourceId===id)item.sourceId=null;item.sourceIds=eventSourceIds(item).filter(sourceId=>sourceId!==id)});save();render()}if(button.classList.contains('delete-event')&&confirm('Usunąć to wydarzenie?')){project.events=project.events.filter(item=>item.id!==id);project.events.forEach(item=>{if(item.relationEventId===id)item.relationEventId=null;if(Array.isArray(item.relations))item.relations=item.relations.filter(relation=>relation.eventId!==id)});save();render()}if(button.classList.contains('delete-character')&&confirm('Usunąć tę postać? Zniknie także z przypisanych wydarzeń.')){project.characters=projectCharacters().filter(character=>character.id!==id);project.events.forEach(item=>item.characterIds=(item.characterIds||[]).filter(characterId=>characterId!==id));save();render()}if(button.classList.contains('delete-world')&&confirm('Usunąć ten świat z kartoteki?')){project.worlds=projectWorlds().filter(world=>world.id!==id);save();render()}});
$('#project-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;event.preventDefault();const name=$('#project-name').value.trim();if(!name)return;const project={id:uid('project'),name,description:$('#project-description').value.trim(),createdAt:new Date().toISOString(),worlds:[],sources:[],characters:[],events:[]};state.projects.push(project);state.activeProjectId=project.id;save();event.currentTarget.reset();$('#project-dialog').close();render();switchView('road')});
$('#source-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;event.preventDefault();const project=activeProject(),title=$('#source-title').value.trim();if(!project||!title)return;const data={title,type:$('#source-type').value,status:$('#source-status').value,date:$('#source-date')?.value||'',dateApprox:$('#source-date-approx')?.checked||false,releaseDate:$('#source-release-date')?.value||'',worldIds:[...$('#source-worlds').querySelectorAll('input:checked')].map(input=>input.value),relatedSourceIds:[...selectedRelatedSourceIds],relationType:$('#source-relation-type')?.value||'',canonStatus:$('#source-canon-status')?.value||''};let sourceId=editingSourceId;if(editingSourceId){const item=project.sources.find(source=>source.id===editingSourceId);if(item)Object.assign(item,data)}else{sourceId=uid('source');project.sources.push({id:sourceId,...data,createdAt:new Date().toISOString()})}const target=sourceDialogTarget;editingSourceId=null;sourceDialogTarget=null;selectedRelatedSourceIds=[];save();event.currentTarget.reset();$('#source-dialog').close();render();if(target==='event'){if(!selectedEventSourceIds.includes(sourceId))selectedEventSourceIds.push(sourceId);populateEventSources()}else switchView('road')});

$('.main').addEventListener('click',event=>{const button=event.target.closest('[data-character-focus]');if(!button)return;selectedCharacterId=button.dataset.characterFocus;roadMode='events';renderRoad();switchView('road')});
migrateLegacySourceTags();applyTheme();render();switchView('road');void runCatalogMigrations();
